'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let F,S,opener=null,toastTimer,animations=[];
function defaults(){return {section:'tasks',role:'admin',dialogOpen:true,selectedTask:null,selectedClient:null,selectedCampaign:'camp01',search:'',clientType:'all',taskDrafts:{},taskReplies:{},chatDrafts:{},threads:{},eventApplied:false,eventBusy:false,epoch:Date.now(),material:'email',audience:false,scrolls:{},chatScrolls:{}};}
function task(id){return F.tasks.find(x=>x.id===id)}function client(id){return F.clients.find(x=>x.id===id)}function campaign(id){return F.campaigns.find(x=>x.id===id)}
function column(t){return t.id==='t02'&&S.eventApplied?'done':t.column}function latest(t){return t.id==='t02'&&S.eventApplied?F.events.taskComplete.latest:t.latest}function campaignStatus(c){return c.id==='camp01'&&S.eventApplied?F.events.taskComplete.campaignStatus:c.status}
function columnLabel(t){return F.columns.find(c=>c.id===column(t)).label}function money(n){return new Intl.NumberFormat('ru-RU').format(n)+' ₽'}
function tell(message){const t=$('#toast');clearTimeout(toastTimer);t.textContent=message;t.hidden=false;toastTimer=setTimeout(()=>t.hidden=true,4500)}
function context(){const base=F.conversations[S.section];let object=base.object,id=S.section==='tasks'?'project':'base';if(S.section==='clients'&&S.selectedClient){id=S.selectedClient;object=client(id).name}if(S.section==='campaigns'){id=S.selectedCampaign;object=campaign(id).name}return {agent:base.agent,object,id,key:S.section+':'+base.agent+':'+id,base};}
function thread(c){if(!S.threads[c.key])S.threads[c.key]=c.base.messages.map(m=>({...m}));return S.threads[c.key]}
function saveMainScroll(){const b=$('.kanban');S.scrolls[S.section]={top:$('#main').scrollTop,left:b?.scrollLeft||0}}
function restoreMainScroll(){const saved=S.scrolls[S.section];if(saved){$('#main').scrollTop=saved.top;const b=$('.kanban');if(b)b.scrollLeft=saved.left}else $('#main').scrollTop=0}
function sectionTo(name,{clientId=null,campaignId=null}={}){saveMainScroll();const old=context();S.chatScrolls[old.key]=$('#messages').scrollTop;S.section=name;if(clientId)S.selectedClient=clientId;if(campaignId)S.selectedCampaign=campaignId;renderMain();renderChat();restoreMainScroll();$$('[data-section]').forEach(b=>b.setAttribute('aria-current',b.dataset.section===name?'page':'false'));location.hash=name;}
function renderMain(){if(S.section==='tasks')renderTasks();else if(S.section==='clients')renderClients();else renderCampaigns()}
function taskCard(t){return `<div class="task-wrap" data-task-wrap="${t.id}"><button class="task-card" data-task="${t.id}" aria-label="${esc(t.title)}"><span class="card-context">${esc(campaign(t.campaignId).name)}</span><span class="card-main"><span class="card-owner">${esc(t.owner)}</span><strong class="card-title">${esc(t.title)}</strong><span class="card-stage">${esc(columnLabel(t))}</span><span class="card-latest">${esc(latest(t))}</span>${t.blocker?`<span class="card-blocker">${esc(t.blocker.reason)}</span>`:''}</span><span class="card-footer ${t.kind==='human'?'human':''}">${t.kind==='human'?'Нужен ваш ответ':column(t)==='done'?'Посмотреть результат':'Уточнить задачу'}<span class="action-cue">${esc(t.kind==='human'?t.requiredAction:'Открыть карточку →')}</span></span></button></div>`}
function renderTasks(){$('#main').innerHTML=`<section class="tasks-view"><div class="section-heading"><div><h2>Задачи команды</h2><p>Планы, готовые материалы и решения, которые ждут вас.</p></div><button class="small-action" id="board-event">Показать обновление команды</button></div><div class="direction-band"><strong>В фокусе: Карелия · зимние выходные</strong><span>Два вопроса менеджеру: аудитория и сервис рассылки</span></div><div class="kanban" aria-label="Доска задач — пять колонок" tabindex="0">${F.columns.map(c=>`<section class="lane" data-column="${c.id}" aria-label="${c.label}"><h3 class="lane-heading"><span>${c.label}</span><span class="count" aria-label="Количество задач">${F.tasks.filter(t=>column(t)===c.id).length}</span></h3><div class="lane-body">${F.tasks.filter(t=>column(t)===c.id).map(taskCard).join('')}${F.tasks.every(t=>column(t)!==c.id)?'<p class="lane-empty">Пока нет задач</p>':''}</div></section>`).join('')}</div></section>`;$('#board-event').onclick=()=>applyEvent();bindTaskButtons($('#main'));}
function bindTaskButtons(root){root.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>openTask(b.dataset.task,b))}
function renderClients(){$('#main').innerHTML=`<section><div class="section-heading"><div><h2>Люди и их планы</h2><p>Шесть карточек. Потребности, известные факты и связанная работа.</p></div></div><div class="client-tools"><input id="client-search" type="search" aria-label="Поиск клиентов" placeholder="Найти клиента или организацию" value="${esc(S.search)}"><select id="client-type" aria-label="Тип клиента"><option value="all">Все клиенты</option><option value="person">Физические лица</option><option value="organization">Организации</option></select></div><div class="dossier-layout"><div class="client-index" aria-label="Индекс клиентов"></div><article class="dossier" id="client-dossier"></article></div></section>`;$('#client-type').value=S.clientType;$('#client-search').oninput=e=>{S.search=e.target.value;renderClientIndex()};$('#client-type').onchange=e=>{S.clientType=e.target.value;renderClientIndex()};renderClientIndex();renderDossier();}
function renderClientIndex(){const list=F.clients.filter(c=>(S.clientType==='all'||c.type===S.clientType)&&c.name.toLocaleLowerCase('ru').includes(S.search.toLocaleLowerCase('ru')));$('.client-index').innerHTML=`<div class="index-heading">КЛИЕНТЫ · ${list.length}</div>`+list.map(c=>`<button class="client-option" data-client="${c.id}" aria-pressed="${S.selectedClient===c.id}"><span>${esc(c.name)}</span><small>${c.type==='person'?'Физическое лицо':'Организация'}</small></button>`).join('')+(list.length?'':'<p class="empty-dossier">Ничего не найдено.<br>Попробуйте другое имя.</p>');$$('.client-option').forEach(b=>b.onclick=()=>{const old=context();S.chatScrolls[old.key]=$('#messages').scrollTop;S.selectedClient=b.dataset.client;renderClientIndex();renderDossier();renderChat()});}
function renderDossier(){const c=client(S.selectedClient);if(!c){$('#client-dossier').innerHTML='<div class="empty-dossier"><p class="eyebrow">КЛИЕНТСКОЕ ДОСЬЕ</p><br>Выберите человека или организацию слева,<br>чтобы увидеть потребность и связанную работу.</div>';return}const linkedTasks=F.tasks.filter(t=>t.clientIds.includes(c.id)),linkedCampaigns=F.campaigns.filter(x=>x.audience.clientIds.includes(c.id));$('#client-dossier').innerHTML=`<p class="record-type">${c.type==='person'?'ФИЗИЧЕСКОЕ ЛИЦО':'ОРГАНИЗАЦИЯ'} / ДОСЬЕ</p><h3>${esc(c.name)}</h3><div class="tags">${c.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><div class="need"><p class="eyebrow">ЗАЧЕМ ЕДЕТ</p><p>${esc(c.knownNeed)}</p></div><dl><dt>Что известно</dt><dd>${esc(c.summary)}</dd><dt>Контакт</dt><dd>${esc(c.contact||'Не указано')}</dd><dt>Даты</dt><dd>Не указано</dd></dl><button id="crm-info" class="text-button">Карточка во внешней CRM ↗</button><p id="crm-status" class="form-status" role="status"></p><div class="record-links"><h4>Связанные задачи</h4>${linkedTasks.map(t=>`<button class="link-button" data-task="${t.id}">${esc(t.title)} →</button>`).join('')}</div><div class="record-links"><h4>Кампании</h4>${linkedCampaigns.map(x=>`<button class="link-button" data-campaign="${x.id}">${esc(x.name)} →</button>`).join('')}</div>`;$('#crm-info').onclick=()=>$('#crm-status').textContent='Внешняя CRM не подключена в демо';bindTaskButtons($('#client-dossier'));$('#client-dossier').querySelectorAll('[data-campaign]').forEach(b=>b.onclick=()=>sectionTo('campaigns',{campaignId:b.dataset.campaign}));}
function renderCampaigns(){const c=campaign(S.selectedCampaign);$('#main').innerHTML=`<section><div class="section-heading"><div><h2>Предложение в деталях</h2><p>${esc(campaignStatus(c))} · ничего не отправлено</p></div></div><label class="index-heading" for="campaign-select">КАМПАНИЯ</label><select class="campaign-selector" id="campaign-select">${F.campaigns.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select><div class="audience-summary"><div><strong>Кому: ${c.audience.count} ${c.id==='camp01'?'клиента':'организации'}</strong><span>${esc(c.audience.criteria)}</span></div><button id="audience-button" aria-expanded="${S.audience}">Посмотреть аудиторию</button></div><div class="audience-list" id="audience-list" ${S.audience?'':'hidden'}>${c.audience.clientIds.map(id=>{const cl=client(id);return `<button data-client-link="${id}">${esc(cl.name)}<small>${cl.type==='person'?'Физлицо':'Организация'} · ${esc(cl.tags.join(', '))}</small></button>`}).join('')}</div><div class="material-tabs" role="group" aria-label="Материалы кампании"><button data-material="email" aria-pressed="${S.material==='email'}">Email-письмо</button><button data-material="sms" aria-pressed="${S.material==='sms'}">SMS</button><button data-material="call" aria-pressed="${S.material==='call'}">Сценарий звонка</button></div><div id="material"></div><p class="material-note">Локальный пример пакета. Реальной отправки, звонка и бронирования нет.</p><div class="related-material">${c.taskIds.map(id=>`<button data-task="${id}">${esc(task(id).title)}</button>`).join('')}</div></section>`;$('#campaign-select').value=c.id;$('#campaign-select').onchange=e=>{const old=context();S.chatScrolls[old.key]=$('#messages').scrollTop;S.selectedCampaign=e.target.value;S.material='email';S.audience=false;renderCampaigns();renderChat()};$('#audience-button').onclick=()=>{S.audience=!S.audience;$('#audience-list').hidden=!S.audience;$('#audience-button').setAttribute('aria-expanded',S.audience)};$$('[data-client-link]').forEach(b=>b.onclick=()=>sectionTo('clients',{clientId:b.dataset.clientLink}));$$('[data-material]').forEach(b=>b.onclick=()=>{S.material=b.dataset.material;$$('[data-material]').forEach(x=>x.setAttribute('aria-pressed',x===b));renderMaterial()});bindTaskButtons($('#main'));renderMaterial();}
function renderMaterial(){const c=campaign(S.selectedCampaign),target=$('#material');if(S.material==='sms'){target.innerHTML=`<article class="compact-material"><p class="eyebrow">КОРОТКОЕ СООБЩЕНИЕ / ЧЕРНОВИК</p><h3>Начало разговора</h3><p>${esc(c.sms)}</p><p class="material-note">Сообщение не отправлено.</p></article>`;return}if(S.material==='call'){target.innerHTML=`<article class="compact-material"><p class="eyebrow">ДЛЯ ЗВОНКА МЕНЕДЖЕРА</p><h3>Сначала — понять планы</h3><p>${esc(c.call.goal)}</p><ol>${c.call.script.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><p class="material-note">Памятка человеку. Демо не совершает звонки.</p></article>`;return}if(!c.email.offers){target.innerHTML=`<div class="email-meta">ТЕМА<br><strong>${esc(c.email.subject)}</strong></div><article class="compact-material"><p class="eyebrow">ЗАМЫСЕЛ / ЕЩЁ НЕ ПИСЬМО</p><h3>Рабочая пауза вне офиса</h3><p>${esc(c.email.intro)}</p><p class="material-note">${esc(c.email.note)}</p></article>`;return}target.innerHTML=`<div class="email-meta">ТЕМА ПИСЬМА<br><strong>${esc(c.email.subject)}</strong><br>${esc(c.email.preheader)}</div><article class="email" aria-label="Предпросмотр email-письма"><div class="email-brand">OpenTour<span>ЛИЧНОЕ ПРЕДЛОЖЕНИЕ</span></div><img class="email-image" src="assets/winter-forest.jpg" width="1920" height="1080" alt="Сосновый лес Карелии под снегом в низком зимнем солнце"><div class="letter-intro"><p class="eyebrow">КАРЕЛИЯ / ЗИМНИЕ ВЫХОДНЫЕ</p><h3>Немного ближе<br>к природе. И друг к другу.</h3><p><strong>${esc(c.email.greeting)}</strong></p><p>${esc(c.email.intro)}</p></div>${c.email.offers.map((offer,i)=>`<section class="offer-story"><div><p class="eyebrow">${i===0?'01 / В СВОЁМ ТЕМПЕ':'02 / НАВСТРЕЧУ ВПЕЧАТЛЕНИЯМ'}</p><h4>${esc(offer.title)}</h4><p>${esc(offer.duration.replace('/',' / '))} · ${i===0?'спокойная программа':'больше открытий'}</p><ul>${offer.highlights.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><strong class="price">${money(offer.demoPriceRub)} <small>${esc(offer.unit)} · демоцена</small></strong><p class="availability">${esc(offer.availability)}</p></div><img src="assets/${i===0?'winter-lake':'winter-forest'}.jpg" width="150" height="210" alt="${i===0?'Заснеженный берег и деревянные дома у озера в Карелии':'Зимние сосны Карелии, освещённые солнцем'}"></section>`).join('')}<div class="letter-ending"><p>Расскажите, какой ритм отдыха ближе вашей семье. Затем обсудим детали и отдельно уточним даты и наличие мест.</p><button class="primary" id="email-cta">${esc(c.email.cta)}</button><small>Открыть связанную задачу менеджеру · не отправляет письмо</small></div><div class="photo-credit">${esc(c.email.note)}<br>Фото: Egor Plenkin, <a href="https://commons.wikimedia.org/wiki/File:Light_over_the_forest_(52667805061).jpg" target="_blank" rel="noreferrer">Light over the forest</a> и <a href="https://commons.wikimedia.org/wiki/File:Lake_Shore_(51795470647).jpg" target="_blank" rel="noreferrer">Lake Shore</a>, <a href="https://creativecommons.org/licenses/by/2.0/" target="_blank" rel="noreferrer">CC BY 2.0</a>. Кадрирование в макете.</div></article>`;$('#email-cta').onclick=e=>openTask('t03',e.currentTarget);}
function renderChat(){const c=context(),m=$('#messages');$('#agent-name').textContent=c.agent;$('#agent-object').textContent=c.object;$('.agent-initial').textContent=c.agent==='Creative'?'C':'O';$('#dialog-hint').textContent='Обсуждение: '+c.object+'. История и черновик принадлежат этому контексту.';$('#chat-recipient').textContent=c.agent;$('#chat-text').value=S.chatDrafts[c.key]||'';$('#chat-text').disabled=S.role!=='admin';$('#chat-send').disabled=S.role!=='admin';$('#role-explanation').hidden=S.role==='admin';$('#chat-status').textContent='';m.innerHTML=thread(c).map(msg=>`<article class="message ${msg.author==='user'?'user':'agent'}"><span class="author">${msg.author==='user'?'Вы · администратор':esc(c.agent)}</span><p>${esc(msg.text)}</p></article>`).join('');m.scrollTop=S.chatScrolls[c.key]??0;syncPanel();}
function syncPanel(){const mobile=innerWidth<=700;const modalPanel=mobile&&S.dialogOpen;$('.masthead').inert=modalPanel;$('#main').inert=modalPanel;$('#conversation').setAttribute('role',modalPanel?'dialog':'complementary');if(modalPanel)$('#conversation').setAttribute('aria-modal','true');else $('#conversation').removeAttribute('aria-modal');$('#conversation').hidden=!S.dialogOpen;$('#dialog-shade').hidden=!(S.dialogOpen&&mobile);$('#workspace').classList.toggle('panel-closed',!S.dialogOpen||mobile);$('#dialog-toggle').setAttribute('aria-expanded',S.dialogOpen);$('#dialog-toggle').innerHTML=mobile?(S.dialogOpen?'Закрыть диалог':'Диалог · '+esc(context().agent)):(S.dialogOpen?'Свернуть диалог <span aria-hidden="true">→</span>':'Открыть диалог <span aria-hidden="true">←</span>');}
function togglePanel(open){const c=context();S.chatScrolls[c.key]=$('#messages').scrollTop;const x=$('.kanban')?.scrollLeft||0,y=$('#main').scrollTop;S.dialogOpen=open;syncPanel();$('#main').scrollTop=y;const b=$('.kanban');if(b)b.scrollLeft=x;if(open&&innerWidth<=700)$('#dialog-close').focus({preventScroll:true});if(!open&&innerWidth<=700)$('#dialog-toggle').focus({preventScroll:true});}
function renderDiscussion(id){const entries=[...(task(id).comments||[]),...(S.taskReplies[id]||[])];$('#task-comments').innerHTML=entries.length?entries.map(e=>`<article class="discussion-entry"><strong>${esc(e.author)}</strong><p>${esc(e.text)}</p></article>`).join(''):'<p class="quiet-note">Пока нет сообщений. Ваш ответ появится здесь.</p>';}
function openTask(id,button){const t=task(id);opener=button;S.selectedTask=id;$('#task-context').textContent=campaign(t.campaignId).name;$('#task-owner').textContent='ОТВЕТСТВЕННЫЙ · '+t.owner;$('#task-title').textContent=t.title;$('#task-status').textContent=columnLabel(t);$('#task-description').textContent=t.description;$('#task-action').textContent=t.requiredAction;$('#task-latest').textContent=latest(t);renderDiscussion(id);$('#task-input-label').textContent=t.kind==='human'?'Ответ по задаче':'Уточнение команде';$('#task-submit').textContent=t.kind==='human'?'Отправить ответ':'Добавить уточнение';$('#task-reply').value=S.taskDrafts[id]||'';$('#task-reply').removeAttribute('aria-invalid');$('#task-form-status').textContent='';$('#task-form-status').className='form-status';$('#task-links').innerHTML=`<button class="link-button" id="task-campaign-link">${esc(campaign(t.campaignId).name)} →</button>`+t.clientIds.map(cid=>`<button class="link-button" data-task-client="${cid}">${esc(client(cid).name)} →</button>`).join('');$('#task-campaign-link').onclick=()=>{closeTask(false);sectionTo('campaigns',{campaignId:t.campaignId})};$$('[data-task-client]').forEach(b=>b.onclick=()=>{closeTask(false);sectionTo('clients',{clientId:b.dataset.taskClient})});$('#task-event-area').hidden=id!=='t02';$('#event-status').textContent=S.eventApplied?'Обновление уже показано. Задача выполнена.':'';if(!$('#task-modal').open)$('#task-modal').showModal();}
function closeTask(restore=true){$('#task-modal').dataset.restore=String(restore);$('#task-modal').close()}
async function applyEvent(){if(S.eventApplied){$('#event-status').textContent='Обновление уже применено. Карточка уже в «Выполнено».';tell('Обновление уже применено — повторного перемещения нет.');return}const epoch=S.epoch,wrapper=$('[data-task-wrap="t02"]'),board=$('.kanban'),x=board?.scrollLeft,y=$('#main').scrollTop;S.eventApplied=true;S.eventBusy=true;const updateModal=()=>{if(S.selectedTask==='t02'&&$('#task-modal').open){$('#task-status').textContent='Выполнено';$('#task-latest').textContent=F.events.taskComplete.latest;$('#event-status').textContent='Подтверждённое обновление показано. Текст и черновик сохранены.'}};const updateCard=()=>{if(wrapper){wrapper.querySelector('.card-stage').textContent='Выполнено';wrapper.querySelector('.card-latest').textContent=F.events.taskComplete.latest;wrapper.querySelector('.card-footer').innerHTML='Посмотреть результат<span class="action-cue">Открыть карточку →</span>'}updateModal();$$('.lane').forEach(l=>l.querySelector('.count').textContent=F.tasks.filter(t=>column(t)===l.dataset.column).length)};const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;if(wrapper&&!reduced){wrapper.style.overflow='hidden';const a=wrapper.animate([{height:wrapper.offsetHeight+'px',opacity:1},{height:'0px',opacity:0}],{duration:180,easing:'ease-in',fill:'forwards'});animations.push(a);await a.finished.catch(()=>{});if(S.epoch!==epoch)return;a.cancel()}if(wrapper){updateCard();const target=$('[data-column="done"] .lane-body');target.querySelector('.lane-empty')?.remove();target.append(wrapper);if(!reduced){const height=wrapper.offsetHeight;const a=wrapper.animate([{height:'0px',opacity:0},{height:height+'px',opacity:1}],{duration:220,easing:'ease-out',fill:'forwards'});animations.push(a);await a.finished.catch(()=>{});if(S.epoch!==epoch)return;a.cancel()}wrapper.style.overflow='';const source=$('[data-column="working"] .lane-body');if(!source.children.length)source.innerHTML='<p class="lane-empty">Пока нет задач</p>'}else{updateModal();if(S.section==='campaigns'){const scroll=$('#main').scrollTop;renderCampaigns();$('#main').scrollTop=scroll}}S.eventBusy=false;if(board)board.scrollLeft=x;$('#main').scrollTop=y;tell('Обновление команды: пакет готов к проверке. Задача выполнена.');}
function reset(){const epoch=S?.epoch;animations.forEach(a=>a.cancel());animations=[];if($('#task-modal').open){opener=null;$('#task-modal').close()}S=defaults();S.epoch=(epoch||0)+1;S.dialogOpen=true;$('#role').value='admin';renderMain();renderChat();$$('[data-section]').forEach(b=>b.setAttribute('aria-current',b.dataset.section==='tasks'?'page':'false'));location.hash='tasks';$('#main').scrollTop=0;tell('Демо сброшено: задачи, администратор, исходные материалы.');}
